int resize_vbar_entry(RDPCLIENT * This, RDPCLIENT * This) { char *data; unsigned int size; unsigned int align; unsigned int align_size; if (This->vbar_info.vbar_end > This->vbar_info.vbar_start) { align = FreeRDPGetBytesPerPixel(This->net); align_size = This->vbar_info.vbar_start * align; align_size = (This->vbar_info.vbar_end - This->vbar_start) * align; This->vbar_start = This->vbar_info.vbar_end; data = winpr_aligned_recalloc(This->vbar_info.vbar_start, This->vbar_info.vbar_end, align, 32); if (!data) return 0; } else { while (This->vbar_info.vbar_start) { memset(data + align_size, 0, align_size); This->vbar_info.vbar_start = data; } if (This->vbar_info.vbar_start) return 0; } return 1; }